CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS company_os_packages (id text PRIMARY KEY CHECK(id ~ '^faivr\.agent\.[a-z0-9]+([._-][a-z0-9]+)*$'), slug text UNIQUE NOT NULL, name text NOT NULL, summary text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS company_os_publishers (key_id text PRIMARY KEY, public_key text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS company_os_package_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id text NOT NULL REFERENCES company_os_packages(id), version text NOT NULL CHECK(version ~ '^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?$'), status text NOT NULL CHECK(status IN ('draft','published','withdrawn')), manifest jsonb NOT NULL, publisher_key_id text REFERENCES company_os_publishers(key_id), publisher_signature text NOT NULL, artifact_url text NOT NULL, artifact_sha256 text NOT NULL CHECK(artifact_sha256 ~ '^sha256:[a-f0-9]{64}$'), monthly_price_cents integer NOT NULL CHECK(monthly_price_cents >= 0), stripe_price_id text, min_company_os_version text NOT NULL, published_at timestamptz, UNIQUE(package_id,version));
CREATE TABLE IF NOT EXISTS company_os_instance_keys (tenant_id uuid NOT NULL, instance_id uuid NOT NULL, key_id text NOT NULL, public_key text NOT NULL, not_before timestamptz NOT NULL DEFAULT now(), not_after timestamptz, revoked_at timestamptz, PRIMARY KEY(tenant_id,instance_id,key_id));
CREATE INDEX IF NOT EXISTS company_os_instance_keys_overlap_idx ON company_os_instance_keys(tenant_id,instance_id,not_before,not_after) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS company_os_request_nonces (tenant_id text NOT NULL, instance_id text NOT NULL, nonce text NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,instance_id,nonce));
CREATE INDEX IF NOT EXISTS company_os_request_nonces_expiry_idx ON company_os_request_nonces(expires_at);
CREATE TABLE IF NOT EXISTS company_os_installations (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, package_id text NOT NULL REFERENCES company_os_packages(id), desired_version_id uuid REFERENCES company_os_package_versions(id), installed_version_id uuid REFERENCES company_os_package_versions(id), subscription_id uuid UNIQUE NOT NULL, checkout_session_id uuid UNIQUE, local_agent_definition_id text, installation_state text NOT NULL CHECK(installation_state IN ('selected','payment_pending','entitled','downloading','installing','active','update_available','disabled','uninstall_pending','removed','failed')), subscription_state text NOT NULL CHECK(subscription_state IN ('checkout_pending','active','past_due','suspended','cancellation_pending_uninstall','cancel_at_period_end','cancelled')), stripe_checkout_session_id text UNIQUE, stripe_subscription_id text UNIQUE, entitled_at timestamptz, installed_at timestamptz, uninstall_request_id uuid, uninstall_requested_at timestamptz, receipt_accepted_at timestamptz, billing_cancel_effective_at timestamptz, billing_stopped_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE company_os_installations ADD COLUMN IF NOT EXISTS checkout_session_id uuid UNIQUE;
ALTER TABLE company_os_installations ALTER COLUMN stripe_checkout_session_id TYPE text USING stripe_checkout_session_id::text;
CREATE INDEX IF NOT EXISTS company_os_installations_tenant_idx ON company_os_installations(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS company_os_idempotency (tenant_id text NOT NULL, idempotency_key text NOT NULL, operation text NOT NULL, request_hash text NOT NULL, status text NOT NULL CHECK(status IN ('processing','completed')), response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,idempotency_key,operation));
CREATE INDEX IF NOT EXISTS company_os_idempotency_expiry_idx ON company_os_idempotency(expires_at);
CREATE TABLE IF NOT EXISTS company_os_archive_receipts (receipt_id uuid PRIMARY KEY, tenant_id uuid NOT NULL, instance_id uuid NOT NULL, installation_id uuid NOT NULL REFERENCES company_os_installations(id), payload jsonb NOT NULL, signature text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS company_os_uninstall_receipts (receipt_id uuid PRIMARY KEY, tenant_id uuid NOT NULL, instance_id uuid NOT NULL, installation_id uuid NOT NULL REFERENCES company_os_installations(id), uninstall_request_id uuid NOT NULL, subscription_id uuid NOT NULL, nonce text NOT NULL, payload jsonb NOT NULL, signature text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,instance_id,nonce));
CREATE TABLE IF NOT EXISTS company_os_billing_acknowledgements (event_id uuid PRIMARY KEY, receipt_id uuid NOT NULL, subscription_id uuid NOT NULL, receipt_state text NOT NULL CHECK(receipt_state IN ('accepted','rejected')), subscription_state text NOT NULL CHECK(subscription_state IN ('checkout_pending','active','past_due','suspended','cancellation_pending_uninstall','cancel_at_period_end','cancelled')), effective_at timestamptz NOT NULL, rejection_reason text, payload jsonb NOT NULL, signature text NOT NULL, UNIQUE(receipt_id,subscription_state));
CREATE TABLE IF NOT EXISTS company_os_webhook_events (provider text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,event_id));
CREATE TABLE IF NOT EXISTS company_os_audit_events (id bigserial PRIMARY KEY, tenant_id text NOT NULL, installation_id uuid, event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
